package main

import (
	"bytes"
	"encoding/gob"
	"encoding/base64"
	"fmt"
	"net/http"
	"os/exec"
	"strings"

	"github.com/gin-gonic/gin"
)

// SessionData holds user session information
type SessionData struct {
	Username string
	Role     string
	Prefs    map[string]string
}

// CommandTask is registered for gob but intended for internal batch processing
type CommandTask struct {
	Name    string
	Command string
	Args    []string
}

func (c *CommandTask) Execute() (string, error) {
	cmd := exec.Command(c.Command, c.Args...)
	var out bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &out
	err := cmd.Run()
	return out.String(), err
}

func init() {
	// Register types for gob encoding/decoding
	gob.Register(&SessionData{})
	gob.Register(&CommandTask{})
	gob.Register(map[string]interface{}{})
}

// deserializeSession decodes a base64-encoded gob payload
func deserializeSession(encoded string) (interface{}, error) {
	data, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		return nil, fmt.Errorf("base64 decode error: %w", err)
	}

	buf := bytes.NewBuffer(data)
	dec := gob.NewDecoder(buf)

	var result interface{}
	if err := dec.Decode(&result); err != nil {
		return nil, fmt.Errorf("gob decode error: %w", err)
	}
	return result, nil
}

func main() {
	r := gin.Default()

	// Health check endpoint
	r.GET("/health", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"status": "ok"})
	})

	// Session restore endpoint - accepts serialized session from cookie or body
	r.POST("/api/v1/session/restore", func(c *gin.Context) {
		var req struct {
			SessionToken string `json:"session_token" binding:"required"`
		}

		if err := c.ShouldBindJSON(&req); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid request"})
			return
		}

		// Basic input validation - check length and characters
		if len(req.SessionToken) > 4096 {
			c.JSON(http.StatusBadRequest, gin.H{"error": "token too large"})
			return
		}

		// Sanitize: reject tokens containing obvious shell metacharacters in plaintext
		if strings.ContainsAny(req.SessionToken, "|;&$`") {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid characters in token"})
			return
		}

		obj, err := deserializeSession(req.SessionToken)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "failed to restore session"})
			return
		}

		// If deserialized object is a CommandTask, execute it (internal batch feature)
		if task, ok := obj.(*CommandTask); ok {
			output, err := task.Execute()
			if err != nil {
				c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
				return
			}
			c.JSON(http.StatusOK, gin.H{"output": output})
			return
		}

		if session, ok := obj.(*SessionData); ok {
			c.JSON(http.StatusOK, gin.H{
				"username": session.Username,
				"role":     session.Role,
			})
			return
		}

		c.JSON(http.StatusBadRequest, gin.H{"error": "unknown session format"})
	})

	// Batch task submission (internal use)
	r.POST("/internal/batch/submit", func(c *gin.Context) {
		var req struct {
			Payload string `json:"payload" binding:"required"`
		}
		if err := c.ShouldBindJSON(&req); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid request"})
			return
		}

		obj, err := deserializeSession(req.Payload)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "decode failed"})
			return
		}

		if task, ok := obj.(*CommandTask); ok {
			output, _ := task.Execute()
			c.JSON(http.StatusOK, gin.H{"result": output})
			return
		}
		c.JSON(http.StatusBadRequest, gin.H{"error": "not a task"})
	})

	r.Run(":8080")
}
